def _validate_no_lone_surrogates(value: Any) -> None:
    if isinstance(value, str):
        for ch in value:
            cp = ord(ch)
            if 0xD800 <= cp <= 0xDFFF:
                raise ValueError(f"JCS: lone surrogate U+{cp:04X} not allowed")
    elif isinstance(value, dict):
        for k, v in value.items():
            _validate_no_lone_surrogates(k)
            _validate_no_lone_surrogates(v)
    elif isinstance(value, (list, tuple)):
        for elem in value:
            _validate_no_lone_surrogates(elem)


def canonical_json(value: Any) -> bytes:
    """Serialize to canonical JSON per RFC 8785 (JCS), mirroring jcs.go."""
    _validate_no_lone_surrogates(value)
    out: List[str] = []
    _format_jcs(value, out)
    return "".join(out).encode("utf-8")


