    def to_canonical_value(self) -> Dict[str, Any]:
        return _clean({
            "protocol": self.protocol,
            "task_id": self.task_id,
            "creator": self.creator,
            "title": self.title,
            "bounty": {"currency": self.bounty.currency, "amount": self.bounty.amount},
            "oracle": _clean({
                "type": self.oracle.type,
                "target": self.oracle.target,
                "assertions": self.oracle.assertions,
                "hermetic": self.oracle.hermetic,
            }),
            "context": _clean({
                "repository": self.context.repository,
                "base_commit": self.context.base_commit,
                "issue_ref": self.context.issue_ref,
