"""VTP-1 Python reference validator — a stdlib-only mirror of internal/vtp (Go).

Implements the same canonicalization and hashing contract as the Go
implementation in internal/vtp/ of xChuCx/agent-memory:

- RFC 8785 (JCS) canonical JSON: UTF-16 code-unit key sorting, ECMAScript
  number serialization (see 7.1.12.1), and the exact escaping table of
  Section 3.2.2.2.
- LF normalization (SAR-002) and bit-exact raw digests (SAR-007 Tier 1).
- ReceiptHash / SpecHash / VerifyHash over the canonical bytes.
- VerifyReceipt dual-oracle evaluation with the same verdict/basis pairs.

Cross-language contract: for any TaskReceipt built from the field values
used in board claim #23166, Python's ReceiptHash and Go's ReceiptHash
(internal/vtp, commit b281e73 and later) produce byte-identical hex.

Verified against Go: receipt hash e536ad8cf230799fa9d8d754f049c1d007d4c
770f101452867d9ec5932c91310 (see tests/test_vtp.py, vector from
TestVTP_ReceiptHash_ZcodeAvikhMatch).
"""

from __future__ import annotations

import hashlib
import json
import math
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

PROTOCOL_VERSION = "VTP/1.0"

# ---------------------------------------------------------------------------
# Digest helpers (mirror of ComputeRawDigest / ComputeDigest, SAR-002/SAR-007)
# ---------------------------------------------------------------------------


def normalize_lf(data: bytes) -> bytes:
    """Canonical LF normalization (SAR-002) prior to hashing."""
    return data.replace(b"\r\n", b"\n")


def compute_raw_digest(data: bytes) -> str:
    """Bit-exact SHA-256 hex over unmodified raw bytes (SAR-007 Tier 1)."""
    return hashlib.sha256(data).hexdigest()


def compute_digest(data: bytes) -> str:
    """Canonical SHA-256 hex with CRLF normalization (LF projection)."""
    return hashlib.sha256(normalize_lf(data)).hexdigest()


@dataclass
class DigestComparison:
    raw_digest: str
    lf_digest: str
    raw_equal: bool
    lf_projection_equal: bool


def compare_digest_projections(a: bytes, b: bytes) -> DigestComparison:
    raw_a, raw_b = compute_raw_digest(a), compute_raw_digest(b)
    lf_a, lf_b = compute_digest(a), compute_digest(b)
    return DigestComparison(raw_a, lf_a, raw_a == raw_b, lf_a == lf_b)


# ---------------------------------------------------------------------------
# RFC 8785 (JCS) canonicalization — mirror of jcs.go
# ---------------------------------------------------------------------------

_SHORT_ESCAPES = {
    0x22: '\\"',  # "
    0x5C: "\\\\",  # \
    0x08: "\\b",
    0x0C: "\\f",
    0x0A: "\\n",
    0x0D: "\\r",
    0x09: "\\t",
}


def _utf16_units(s: str) -> List[int]:
    """UTF-16 code unit sequence of a Python string (surrogate pairs folded)."""
    return _units(s)


def _units(s: str) -> List[int]:
    out = []
    for ch in s:
        cp = ord(ch)
        if cp <= 0xFFFF:
            out.append(cp)
        else:
            cp -= 0x10000
            out.append(0xD800 + (cp >> 10))
            out.append(0xDC00 + (cp & 0x3FF))
    return out


def _jcs_string(s: str) -> str:
    parts = ['"']
    for ch in s:
        cp = ord(ch)
        if 0xD800 <= cp <= 0xDFFF:
            # Python strings can carry lone surrogates via surrogateescape;
            # Go rejects them in validateNoLoneSurrogates/formatJCSString.
            raise ValueError(f"JCS: lone surrogate U+{cp:04X} not allowed")
        esc = _SHORT_ESCAPES.get(cp)
        if esc is not None:
            parts.append(esc)
        elif cp < 0x20:
            parts.append(f"\\u{cp:04x}")
        else:
            parts.append(ch)
    parts.append('"')
    return "".join(parts)


def _shift_to_plain(mant: str, exp: int) -> str:
    """Reposition the decimal point of a repr-style mantissa.

    repr() already yields the shortest round-trip digits; converting an
    exponential form to plain notation is a point shift, never a
    re-formatting (re-formatting at fixed precision would break round-trip).
    """
    sign = ""
    if mant.startswith("-"):
        sign, mant = "-", mant[1:]
    if "." in mant:
        ip, fp = mant.split(".")
    else:
        ip, fp = mant, ""
    digits = ip + fp
    point = len(ip) + exp
    if point <= 0:
        return sign + "0." + "0" * (-point) + digits
    if point >= len(digits):
        return sign + digits + "0" * (point - len(digits))
    return sign + digits[:point] + "." + digits[point:]


def _jcs_number(value: Any) -> str:
    """ECMAScript Number::toString serialization per RFC 8785 Section 3.2.2.3.

    Mirrors formatJCSNumber: shortest round-trip digits (repr), plain decimal
    notation for 1e-6 <= |x| < 1e21, ECMAScript-style exponent otherwise
    (no '+', no leading zeros), and -0 collapses to 0.
    """
    if isinstance(value, bool):
        raise TypeError("bool is not a number here")

    if isinstance(value, int):
        # Integral literals inside the plain band print as themselves;
        # at or beyond 1e21 the double is no longer integral (1e21 -> "1e21").
        if -1e21 < value < 1e21:
            return str(value)
        value = float(value)

    f = float(value)
    if math.isnan(f) or math.isinf(f):
        raise ValueError("JCS: NaN and Infinity are not permitted in JSON")
    if f == 0:
        # Covers both 0 and -0 (mirrors the "-0" branch in formatJCSNumber).
        return "0"

    s = repr(f)
    if "e" in s:
        mant, _, exp_s = s.partition("e")
        exp_i = int(exp_s)
        if 1e-6 <= abs(f) < 1e21:
            # Plain-decimal band: shift the point on the shortest digits.
            s = _shift_to_plain(mant, exp_i)
        else:
            # ECMAScript exponent: bare mantissa, exponent without '+' or
            # leading zeros ("1e21", "1e-7").
            if "." in mant:
                mant = mant.rstrip("0").rstrip(".")
            return f"{mant}e{exp_i}"

    if "." in s:
        # repr(100.0) is "100.0"; ECMAScript prints "100".
        s = s.rstrip("0").rstrip(".")
    return s


def _format_jcs(value: Any, out: List[str]) -> None:
    if value is None:
        out.append("null")
    elif value is True:
        out.append("true")
    elif value is False:
        out.append("false")
